import { NextFunction, Request, Response } from 'express';
import {
  DomainError,
  InsufficientStockError,
  InvalidStatusTransitionError,
  NotFoundError,
  ValidationError,
} from '../../../domain/errors/DomainErrors';

function statusFor(error: DomainError): number {
  if (error instanceof ValidationError) return 400;
  if (error instanceof NotFoundError) return 404;
  if (error instanceof InsufficientStockError || error instanceof InvalidStatusTransitionError) return 409;
  return 422;
}

function isMalformedJson(error: unknown): boolean {
  return (
    typeof error === 'object' &&
    error !== null &&
    (error as { type?: unknown }).type === 'entity.parse.failed'
  );
}

/** Maps domain errors to HTTP responses; anything unexpected becomes a 500. */
export function errorHandler(error: unknown, _req: Request, res: Response, _next: NextFunction): void {
  if (error instanceof DomainError) {
    res.status(statusFor(error)).json({ error: { code: error.code, message: error.message } });
    return;
  }
  if (isMalformedJson(error)) {
    res.status(400).json({ error: { code: 'MALFORMED_JSON', message: 'Request body is not valid JSON' } });
    return;
  }
  console.error(error);
  res.status(500).json({ error: { code: 'INTERNAL_ERROR', message: 'An unexpected error occurred' } });
}

=====SOURCE-END=====

